// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
        // test contract is deployer => owner; initialize owner balances
        c.XBornID();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(amount > 0);
        vm.assume(amount <= 200000000e18);

        // give actor a non-zero pre-existing balance via owner transfer
        c.transfer(actor, amount);
        assertEq(c.balanceOf(actor), amount);

        uint256 pre = c.balanceOf(actor);
        uint256 distValue = c.value();
        vm.assume(distValue > 0);
        vm.assume(distValue <= c.totalRemaining());

        // actor claims free tokens
        vm.prank(actor);
        c.getTokens();

        // reference: additive distribution => balance strictly grows by distValue
        assertTrue(c.balanceOf(actor) == pre + distValue);
    }
}
